export class ReturnRequestsPage {
  private http = inject(HttpClient);
  private toast = inject(ToastService);
  private auth = inject(AuthService);

  readonly tableKey = 'return-requests.component';

  /** base columns — the actions column is appended for users who may decide */
  private readonly baseColumns = [
    { field: 'custody_id', header: 'custody.return_requests.col_number', sortable: true },
    { field: 'agent', header: 'custody.return_requests.col_agent', sortable: true },
    { field: 'requested_by', header: 'custody.return_requests.col_requested_by', sortable: true },
    { field: 'amount', header: 'common.amount', sortable: true, numeric: true },
    { field: 'reason', header: 'custody.return_requests.col_reason', sortable: true },
    { field: 'status', header: 'common.status', sortable: true },
    { field: 'created_at', header: 'common.date', sortable: true },
    { field: 'approved_by', header: 'custody.return_requests.col_approved_by', sortable: true },
    { field: 'approved_at', header: 'custody.return_requests.col_approved_at', sortable: true },
    { field: 'rejection_reason', header: 'custody.return_requests.col_rejection', sortable: false },
  ];

  columns = computed(() =>
    this.canDecide()
      ? [...this.baseColumns, { field: 'actions', header: 'common.actions', sortable: false }]
      : this.baseColumns,
  );

  readonly statusTabs = [
    { value: 'all', label: 'custody.return_requests.tab_all' },
    { value: 'pending', label: 'custody.return_requests.tab_pending' },
    { value: 'approved', label: 'custody.return_requests.tab_approved' },
    { value: 'rejected', label: 'custody.return_requests.tab_rejected' },
  ];

  params = signal<ReturnRequestParams>({ page: 1, per_page: 25, q: '', status: 'all' });

  /** the active filter[...] values — forwarded verbatim (T7-07 server contract) */
  filterBag: Record<string, unknown> = {};

  /** T7-07: the endpoint's declared allowlist drives the table's Filters control */
  readonly metaFilters = computed(() => apiFilterDefs(this.data.value()?.meta));

  /** the table emits the full query — filters reach the server (T7-07) */
  onQuery(query: TableQuery): void {
    this.filterBag = query.filters;
    this.params.update((p) => ({
      ...p,
      page: query.page,
      per_page: query.perPage,
      sort: query.sort !== '' ? query.sort : p.sort,
      q: query.q,
    }));
    this.data.reload();
  }

  /** T6-11: status tabs drive the same `status` query param */
  statusTab = signal<string>('all');
  readonly statusTabDefs: AppTab[] = [
    { id: 'all', label: 'custody.list.tab_all' },
    { id: 'pending', label: 'enums.return_request.pending' },
    { id: 'approved', label: 'enums.return_request.approved' },
    { id: 'rejected', label: 'enums.return_request.rejected' },
  ];

  data = resource<ListResponse<Row>, unknown>({
    loader: () =>
      firstValueFrom(this.http.get<ListResponse<Row>>('/custodies/return-requests', { params: { ...cleanParams(this.params()), ...filterParams(this.filterBag) } })),
  });

  /** treasuries for the approve-with-treasury select */
  lookups = resource<Lookups, unknown>({
    loader: () => firstValueFrom(this.http.get<{ data: Lookups }>('/lookups')).then((r) => r.data),
  });

  /** actions are shown to return approvers: manage_treasury (with-treasury) or approve_custody (owner) */
  canDecide = computed(() => this.auth.can('may_manage_treasury') || this.auth.can('may_approve_custody'));
  canManageTreasury = computed(() => this.auth.can('may_manage_treasury'));

  /** the summary block only exists once the API provides counters — tiles then light up */
  hasSummary = computed(() => Object.keys(this.data.value()?.meta.summary ?? {}).length > 0);

  active = signal<Row | null>(null);
  approveTreasuryId = signal<number | null>(null);
  sending = signal(false);
  actionError = signal<HttpErrorResponse | null>(null);

  private confirm = viewChild.required(ConfirmDialogComponent);
  private reason = viewChild.required(ReasonDialogComponent);
  private readonly treasuryDlg = viewChild.required<FormDialogComponent>('treasuryDlg');

  treasuries(): { id: number; name: string; balance: string }[] {
    return this.lookups.value()?.treasuries ?? [];
  }

  selectedTreasury(): { id: number; name: string; balance: string } | null {
    const id = this.approveTreasuryId();
    return this.treasuries().find((t) => t.id === id) ?? null;
  }

  /** the treasury receives the returned amount — balance after approval */
  balanceAfter(treasury: { balance: string }): string {
    const row = this.active();
    return (parseFloat(treasury.balance) + parseFloat(row?.amount ?? '0')).toFixed(2);
  }

  summaryValue(key: string): string {
    const value = this.data.value()?.meta.summary?.[key];
    return typeof value === 'number' || typeof value === 'string' ? String(value) : '0';
  }

  setParam(key: string, value: string): void {
    this.params.update((p) => ({ ...p, [key]: value, page: 1 }));
    this.data.reload();
  }

  onSearch(term: string): void { this.setParam('q', term); }

  /** pending-only decide actions: approve picks the allowed path, reject requires a reason */
  actionsFor(row: Row): RowActionItem[] {
    return [
      {
        icon: 'check',
        label: 'custody.return_requests.approve',
        handler: () => { this.openApprove(row); },
        visible: row.status === 'pending',
      },
      {
        icon: 'x',
        label: 'custody.return_requests.reject',
        severity: 'danger',
        handler: () => { this.openReject(row); },
        visible: row.status === 'pending',
      },
    ];
  }

  onPage(event: { page: number; per_page: number; sort?: string }): void {
    const current = this.params();
    const sort = event.sort ?? '';
    if (current.page === event.page && current.per_page === event.per_page && current.sort === sort) {
      return;
    }
    this.params.update((p) => ({ ...p, page: event.page, per_page: event.per_page, sort }));
    this.data.reload();
  }

  /** pending-only action: pick the approve path the current user is allowed to use */
  openApprove(row: Row): void {
    this.active.set(row);
    this.actionError.set(null);
    if (this.canManageTreasury()) {
      this.approveTreasuryId.set(null);
      this.treasuryDlg().open();
    } else {
      this.confirm().open();
    }
  }

  openReject(row: Row): void {
    this.active.set(row);
    this.actionError.set(null);
    this.reason().open();
  }

  /** plain approve — custody owner only; the return executes immediately */
  submitApprove(): void {
    const row = this.active();
    if (row === null) {
      return;
    }
    void this.send(`/custody-return-requests/${row.id}/approve`);
  }

  /** accountant/manager approve — the money lands in the chosen treasury */
  submitApproveWithTreasury(): void {
    const row = this.active();
    const treasuryId = this.approveTreasuryId();
    if (row === null || treasuryId === null) {
      return;
    }
    void this.send(`/custody-return-requests/${row.id}/approve-with-treasury`, { treasury_id: treasuryId });
  }

  submitReject(reason: string): void {
    const row = this.active();
    if (row === null) {
      return;
    }
    void this.send(`/custody-return-requests/${row.id}/reject`, { rejection_reason: reason });
  }

  private send(path: string, body: Record<string, unknown> = {}): Promise<void> {
    this.sending.set(true);
    this.actionError.set(null);
    return firstValueFrom(this.http.post<ActionResponse>(path, body))
      .then((res) => {
        this.sending.set(false);
        this.treasuryDlg().close();
        this.reason().done();
        this.toast.success(res.message);
        this.data.reload();
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        const response = err instanceof HttpErrorResponse ? err : null;
        this.actionError.set(response);
        if (response) {
          this.toast.apiError(response.error?.message ?? 'errors.generic', response.error?.code);
        }
      });
  }
}

function cleanParams(params: object): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(params)) {
    if (value !== null && value !== undefined && value !== '' && value !== 'all') {
      result[key] = String(value);
    }
  }
  return result;
}
